"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["17370"],{80360(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>d,frontMatter:()=>i,contentTitle:()=>o,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"tangfen/challengechan","title":"","description":"Miss Chan wrote on the 14th \\"Tangfen, your interpretation of Marx\'s labor theory of value has serious problems.\\" I haven\'t had a chance to rebut until now. We Chinese believe in reciprocity, especially us Chinese men -- not responding would break protocol. Regarding Marx\'s value theory, Miss Chan dismissed it from on high with a single \\"the production category determines the exchange category,\\" and I have nothing more to say about that, so I\'ll change the topic to challenge Miss Chan.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/challengechan.md","sourceDirName":"tangfen","slug":"/tangfen/challengechan","permalink":"/en/tangfen/challengechan","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"challengechan","title":"","hide_table_of_contents":true,"sidebar_label":"Ms. Chan, in the spirit of reciprocity, I challenge you!"},"sidebar":"tangfenSidebar","previous":{"title":"[Repost] On a mistranslation in the Chinese edition of \\"Das Kapital\\" regarding labor value theory (Note: reposted by Chan)","permalink":"/en/tangfen/someproblemofcaptical"},"next":{"title":"What China needs is real men","permalink":"/en/tangfen/chinaneedmen"}}'),s=t(74848),r=t(28453);let i={id:"challengechan",title:"",hide_table_of_contents:!0,sidebar_label:"Ms. Chan, in the spirit of reciprocity, I challenge you!"},o="Miss Chan, Courtesy Demands Reciprocity -- I'm Challenging You!",h={},l=[];function c(e){let n={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"miss-chan-courtesy-demands-reciprocity----im-challenging-you",children:"Miss Chan, Courtesy Demands Reciprocity -- I'm Challenging You!"})}),"\n",(0,s.jsx)(n.p,{children:"Miss Chan wrote on the 14th \"Tangfen, your interpretation of Marx's labor theory of value has serious problems.\" I haven't had a chance to rebut until now. We Chinese believe in reciprocity, especially us Chinese men -- not responding would break protocol. Regarding Marx's value theory, Miss Chan dismissed it from on high with a single \"the production category determines the exchange category,\" and I have nothing more to say about that, so I'll change the topic to challenge Miss Chan."}),"\n",(0,s.jsx)(n.p,{children:"Recently there was a non-forum-member writing about Buddhist dharma, and I replied a few times. He insisted I write a post and even sent me text messages. So, since the weather has been hot these past couple of days, I'll use the hot weather as my theme to answer the non-member's question while casually challenging Miss Chan. I know Miss Chan's classical poetry skills are formidable, but I shall advance despite the difficulty, using classical poetic form to express my views. As for whether the non-member can understand -- I don't care, as long as I believe Miss Chan can understand. The challenge topic for Miss Chan is this: regarding Buddhism, Miss Chan must reply with a poem matching my rhyme scheme. Otherwise Miss Chan loses."}),"\n",(0,s.jsx)(n.p,{children:"I'm a man's man. Even if Miss Chan loses, I won't make her admit fault -- unlike Miss Chan, who made me admit fault. Enough idle talk. Here comes my poem about Buddhist dharma through the topic of hot weather. Miss Chan, be ready to receive it:"}),"\n",(0,s.jsxs)(n.p,{children:["The summer heat, when did it ever torment? ",(0,s.jsx)("br",{}),"\nIt is only people who are deluded and bent. ",(0,s.jsx)("br",{}),"\nWater and fire, their natures like illusion, ",(0,s.jsx)("br",{}),"\nFish and shrimp enter the pot of their own volition. ",(0,s.jsx)("br",{}),"\nAll things take form between void and being, ",(0,s.jsx)("br",{}),"\nRound or square -- what can bind their freeing? ",(0,s.jsx)("br",{}),"\nGlass and mud are one in body, ",(0,s.jsx)("br",{}),"\nEternally reflecting, shining embody. ",(0,s.jsx)("br",{}),"\nThe blind do not blame their eyes, ",(0,s.jsx)("br",{}),"\nNot a matter of light strong or otherwise. ",(0,s.jsx)("br",{}),"\nTrees dense or sparse in their array, ",(0,s.jsx)("br",{}),"\nThe cicada's tune finds no branch to stay. ",(0,s.jsx)("br",{}),"\nDusty thoughts chase after the cart, ",(0,s.jsx)("br",{}),"\nHow can they preserve the wheel's impart? ",(0,s.jsx)("br",{}),"\nProsperity flourishes then decays, ",(0,s.jsx)("br",{}),"\nLove and joy were always thin in their ways. ",(0,s.jsx)("br",{}),"\nA great furnace between heaven and earth, ",(0,s.jsx)("br",{}),"\nBirth and death -- who can seize their worth? ",(0,s.jsx)("br",{}),"\nDeparting thoughts ride the wind afar, ",(0,s.jsx)("br",{}),"\nPassing over mountains and ravines ajar. ",(0,s.jsx)("br",{}),"\nNo-self, no no-self in the end, ",(0,s.jsx)("br",{}),"\nIf you don't understand, don't pretend."]})]})}function d(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>i,x:()=>o});var a=t(96540);let s={},r=a.createContext(s);function i(e){let n=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(r.Provider,{value:n},e.children)}}}]);